  create table "public"."risks" (
    "id" uuid not null default gen_random_uuid(),
    "organization_id" uuid not null,
    "title" text not null,
    "description" text not null,
    "risk_code" text,
    "risk_category" text not null,
    "risk_type" text,
    "probability" text not null,
    "impact" text not null,
    "risk_score" integer generated always as ((
CASE probability
    WHEN 'very_low'::text THEN 1
    WHEN 'low'::text THEN 2
    WHEN 'medium'::text THEN 3
    WHEN 'high'::text THEN 4
    WHEN 'very_high'::text THEN 5
    ELSE NULL::integer
END *
CASE impact
    WHEN 'negligible'::text THEN 1
    WHEN 'minor'::text THEN 2
    WHEN 'moderate'::text THEN 3
    WHEN 'major'::text THEN 4
    WHEN 'critical'::text THEN 5
    ELSE NULL::integer
END)) stored,
    "risk_level" text generated always as (
CASE
    WHEN ((
    CASE probability
        WHEN 'very_low'::text THEN 1
        WHEN 'low'::text THEN 2
        WHEN 'medium'::text THEN 3
        WHEN 'high'::text THEN 4
        WHEN 'very_high'::text THEN 5
        ELSE NULL::integer
    END *
    CASE impact
        WHEN 'negligible'::text THEN 1
        WHEN 'minor'::text THEN 2
        WHEN 'moderate'::text THEN 3
        WHEN 'major'::text THEN 4
        WHEN 'critical'::text THEN 5
        ELSE NULL::integer
    END) <= 4) THEN 'low'::text
    WHEN ((
    CASE probability
        WHEN 'very_low'::text THEN 1
        WHEN 'low'::text THEN 2
        WHEN 'medium'::text THEN 3
        WHEN 'high'::text THEN 4
        WHEN 'very_high'::text THEN 5
        ELSE NULL::integer
    END *
    CASE impact
        WHEN 'negligible'::text THEN 1
        WHEN 'minor'::text THEN 2
        WHEN 'moderate'::text THEN 3
        WHEN 'major'::text THEN 4
        WHEN 'critical'::text THEN 5
        ELSE NULL::integer
    END) <= 9) THEN 'medium'::text
    WHEN ((
    CASE probability
        WHEN 'very_low'::text THEN 1
        WHEN 'low'::text THEN 2
        WHEN 'medium'::text THEN 3
        WHEN 'high'::text THEN 4
        WHEN 'very_high'::text THEN 5
        ELSE NULL::integer
    END *
    CASE impact
        WHEN 'negligible'::text THEN 1
        WHEN 'minor'::text THEN 2
        WHEN 'moderate'::text THEN 3
        WHEN 'major'::text THEN 4
        WHEN 'critical'::text THEN 5
        ELSE NULL::integer
    END) <= 16) THEN 'high'::text
    ELSE 'critical'::text
END) stored,
    "status" text not null default 'identified'::text,
    "source" text,
    "triggers" text[],
    "affected_areas" text[],
    "related_project_id" uuid,
    "potential_cost_min" numeric(15,2),
    "potential_cost_max" numeric(15,2),
    "currency" text default 'USD'::text,
    "identified_date" date not null default CURRENT_DATE,
    "target_mitigation_date" date,
    "last_review_date" date,
    "review_frequency_days" integer default 90,
    "owner_id" uuid,
    "department_id" uuid,
    "created_at" timestamp with time zone default now(),
    "updated_at" timestamp with time zone default now(),
    "created_by" uuid,
    "notes" text,
    "tags" text[]
      );


alter table "public"."risks" enable row level security;


