alter table "public"."risk_register" alter column "risk_score" set default (
CASE probability
    WHEN 'rare'::text THEN 1
    WHEN 'unlikely'::text THEN 2
    WHEN 'possible'::text THEN 3
    WHEN 'likely'::text THEN 4
    WHEN 'almost_certain'::text THEN 5
    ELSE NULL::integer
END *
CASE impact
    WHEN 'negligible'::text THEN 1
    WHEN 'minor'::text THEN 2
    WHEN 'moderate'::text THEN 3
    WHEN 'major'::text THEN 4
    WHEN 'catastrophic'::text THEN 5
    ELSE NULL::integer
END);

