  create policy "investment_rounds_portal_isolation"
  on "public"."investment_rounds"
  as permissive
  for select
  to public
using (((EXISTS ( SELECT 1
   FROM (public.user_roles ur
     JOIN public.platform_users pu ON ((pu.id = ur.platform_user_id)))
  WHERE ((pu.auth_user_id = auth.uid()) AND (ur.role_code = ANY (ARRAY['LEGEND_SUPER_ADMIN'::text, 'LEGEND_ADMIN'::text, 'ATLVS_SUPER_ADMIN'::text, 'ATLVS_ADMIN'::text]))))) OR (id IN ( SELECT investments.round_id
   FROM public.investments
  WHERE (investments.investor_id IN ( SELECT portal_user_entity_access.entity_id
           FROM public.portal_user_entity_access
          WHERE ((portal_user_entity_access.user_id IN ( SELECT platform_users.id
                   FROM public.platform_users
                  WHERE (platform_users.auth_user_id = auth.uid()))) AND (portal_user_entity_access.entity_type = 'investor'::text) AND ((portal_user_entity_access.expires_at IS NULL) OR (portal_user_entity_access.expires_at > now())))))))));



